body:
It seems that `RenderingDevice.texture_clear()` is doing different things depending on the used graphics driver.
When manually "clearing" the textures using a compute shader, I get the same result with both drivers.

Invoking the compute shader:
```gdscript
func _ready():
	RenderingServer.call_on_render_thread(create_textures)
	RenderingServer.call_on_render_thread(clear_textures_compute)
	return

func clear_textures_compute():
	var main_rd = RenderingServer.get_rendering_device()
	var shader_file := load("res://shader.glsl")
	var shader_spirv: RDShaderSPIRV = shader_file.get_spirv()
	var shader := main_rd.shader_create_from_spirv(shader_spirv)
	var pipeline := main_rd.compute_pipeline_create(shader)

	var uniform_0 := RDUniform.new()
	uniform_0.uniform_type = RenderingDevice.UNIFORM_TYPE_IMAGE
	uniform_0.binding = 0
	uniform_0.add_id(texture_0.texture_rd_rid)
	var uniform_1 := RDUniform.new()
	uniform_1.uniform_type = RenderingDevice.UNIFORM_TYPE_IMAGE
	uniform_1.binding = 1
	uniform_1.add_id(texture_1.texture_rd_rid)
	var uniform_2 := RDUniform.new()
	uniform_2.uniform_type = RenderingDevice.UNIFORM_TYPE_IMAGE
	uniform_2.binding = 2
	uniform_2.add_id(texture_2.texture_rd_rid)
	var uniform_3 := RDUniform.new()
	uniform_3.uniform_type = RenderingDevice.UNIFORM_TYPE_IMAGE
	uniform_3.binding = 3
	uniform_3.add_id(texture_3.texture_rd_rid)
	var uniform_set := main_rd.uniform_set_create([uniform_0, uniform_1, uniform_2, uniform_3], shader, 0)

	var clear_color = Color.HOT_PINK
	var push_constant: PackedFloat32Array = PackedFloat32Array()
	push_constant.push_back(clear_color.r)
	push_constant.push_back(clear_color.g)
	push_constant.push_back(clear_color.b)
	push_constant.push_back(clear_color.a)

	var compute_list := main_rd.compute_list_begin()
	main_rd.compute_list_bind_compute_pipeline(compute_list, pipeline)
	main_rd.compute_list_bind_uniform_set(compute_list, uniform_set, 0)
	main_rd.compute_list_set_push_constant(compute_list, push_constant.to_byte_array(), push_constant.size() * 4)
	main_rd.compute_list_dispatch(compute_list, 32, 32, 1)
	main_rd.compute_list_end()

	# cleanup
	main_rd.free_rid(shader)
	return
```

The compute shader:
```glsl
#[compute]
#version 450

layout(local_size_x = 8, local_size_y = 8, local_size_z = 1) in;

layout(rgba8, set = 0, binding = 0) uniform restrict writeonly image2D texture_0;
layout(rgba32f, set = 0, binding = 1) uniform restrict writeonly image2D texture_1;
layout(r8, set = 0, binding = 2) uniform restrict writeonly image2D texture_2;
layout(r32f, set = 0, binding = 3) uniform restrict writeonly image2D texture_3;

layout(push_constant, std430) uniform Params {
	vec4 clear_color;
} params;


void main() {
	ivec2 uv = ivec2(gl_GlobalInvocationID.xy);
	imageStore(texture_0, uv, params.clear_color);
	imageStore(texture_1, uv, params.clear_color);
	imageStore(texture_2, uv, params.clear_color);
	imageStore(texture_3, uv, params.clear_color);
}
```

